@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@400;500;600;700;800;900&family=Poppins:wght@300;400;500;600;700&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  /* StudyCore Dark Theme (Default) */
  --background: hsl(0, 0%, 0%);
  --foreground: hsl(0, 0%, 100%);
  --card: hsl(0, 0%, 8%);
  --card-foreground: hsl(0, 0%, 95%);
  --popover: hsl(0, 0%, 5%);
  --popover-foreground: hsl(0, 0%, 95%);
  --primary: hsl(180, 100%, 50%);
  --primary-foreground: hsl(0, 0%, 0%);
  --secondary: hsl(0, 0%, 12%);
  --secondary-foreground: hsl(0, 0%, 100%);
  --muted: hsl(0, 0%, 16%);
  --muted-foreground: hsl(0, 0%, 70%);
  --accent: hsl(180, 100%, 50%);
  --accent-foreground: hsl(0, 0%, 0%);
  --destructive: hsl(0, 84%, 60%);
  --destructive-foreground: hsl(0, 0%, 100%);
  --border: hsl(0, 0%, 20%);
  --input: hsl(0, 0%, 8%);
  --ring: hsl(180, 100%, 50%);
  --chart-1: hsl(180, 100%, 50%);
  --chart-2: hsl(120, 100%, 50%);
  --chart-3: hsl(60, 100%, 50%);
  --chart-4: hsl(240, 100%, 50%);
  --chart-5: hsl(300, 100%, 50%);

  /* StudyCore Enhanced Colors */
  --neon-cyan: hsl(180, 100%, 50%);
  --neon-green: hsl(120, 100%, 50%);
  --neon-yellow: hsl(60, 100%, 50%);
  --neon-red: hsl(0, 100%, 62%);
  --neon-purple: hsl(270, 100%, 60%);
  --neon-blue: hsl(240, 100%, 60%);
  --dark-primary: hsl(0, 0%, 0%);
  --dark-secondary: hsl(0, 0%, 8%);
  --dark-tertiary: hsl(0, 0%, 16%);

  /* Gradient Variables */
  --gradient-primary: linear-gradient(135deg, hsl(180, 100%, 50%) 0%, hsl(240, 100%, 60%) 100%);
  --gradient-secondary: linear-gradient(135deg, hsl(270, 100%, 60%) 0%, hsl(0, 100%, 62%) 100%);
  --gradient-accent: linear-gradient(90deg, hsl(180, 100%, 50%) 0%, hsl(120, 100%, 50%) 100%);

  /* Fonts */
  --font-orbitron: 'Orbitron', monospace;
  --font-poppins: 'Poppins', sans-serif;
  --font-sans: 'Poppins', sans-serif;
  --font-serif: Georgia, serif;
  --font-mono: 'Orbitron', monospace;

  --radius: 0.5rem;
}

.light {
  /* StudyCore Light Theme */
  --background: hsl(0, 0%, 100%);
  --foreground: hsl(0, 0%, 0%);
  --card: hsl(0, 0%, 95%);
  --card-foreground: hsl(0, 0%, 10%);
  --popover: hsl(0, 0%, 100%);
  --popover-foreground: hsl(0, 0%, 0%);
  --primary: hsl(0, 0%, 20%);
  --primary-foreground: hsl(0, 0%, 100%);
  --secondary: hsl(0, 0%, 90%);
  --secondary-foreground: hsl(0, 0%, 0%);
  --muted: hsl(0, 0%, 90%);
  --muted-foreground: hsl(0, 0%, 45%);
  --accent: hsl(0, 0%, 20%);
  --accent-foreground: hsl(0, 0%, 100%);
  --destructive: hsl(0, 84%, 60%);
  --destructive-foreground: hsl(0, 0%, 100%);
  --border: hsl(0, 0%, 85%);
  --input: hsl(0, 0%, 95%);
  --ring: hsl(0, 0%, 20%);

  /* Light mode neon colors become darker */
  --neon-cyan: hsl(0, 0%, 20%);
  --neon-green: hsl(0, 0%, 20%);
  --neon-yellow: hsl(0, 0%, 20%);
  --neon-red: hsl(0, 0%, 20%);
  --dark-primary: hsl(0, 0%, 100%);
  --dark-secondary: hsl(0, 0%, 95%);
  --dark-tertiary: hsl(0, 0%, 90%);
}

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply bg-background text-foreground font-poppins antialiased min-h-screen;
    transition: all 0.3s ease;
  }

  /* Custom scrollbar */
  ::-webkit-scrollbar {
    width: 8px;
  }

  ::-webkit-scrollbar-track {
    background: var(--dark-secondary);
  }

  ::-webkit-scrollbar-thumb {
    background: var(--neon-cyan);
    border-radius: 0px;
  }

  .light ::-webkit-scrollbar-track {
    background: var(--border);
  }

  .light ::-webkit-scrollbar-thumb {
    background: var(--primary);
  }
}

@layer components {
  /* StudyCore specific components */
  .font-orbitron {
    font-family: var(--font-orbitron);
  }

  .font-poppins {
    font-family: var(--font-poppins);
  }

  /* Neon glow effects */
  .neon-glow {
    box-shadow: 0 0 20px hsla(180, 100%, 50%, 0.5);
  }

  .neon-glow-hover {
    transition: all 0.3s ease;
  }

  .neon-glow-hover:hover {
    box-shadow: 0 0 25px hsla(180, 100%, 50%, 0.6);
    transform: translateY(-2px);
  }

  .light .neon-glow-hover:hover {
    box-shadow: 0 0 25px hsla(0, 0%, 0%, 0.3);
    transform: translateY(-2px);
  }

  /* Text glow animations */
  .text-glow-pulse {
    animation: glow-pulse 2s ease-in-out infinite alternate;
  }

  @keyframes glow-pulse {
    from { 
      text-shadow: 0 0 10px hsla(180, 100%, 50%, 0.5); 
    }
    to { 
      text-shadow: 0 0 20px hsla(180, 100%, 50%, 0.8); 
    }
  }

  .light .text-glow-pulse {
    animation: none;
    text-shadow: none;
  }

  /* StudyCore Brand Glow Effect */
  .studycore-glow {
    text-shadow: 
      0 0 5px hsl(var(--neon-cyan)),
      0 0 10px hsl(var(--neon-cyan)),
      0 0 15px hsl(var(--neon-cyan)),
      0 0 20px hsl(var(--neon-cyan));
    animation: studycore-pulse 3s ease-in-out infinite alternate;
  }

  @keyframes studycore-pulse {
    from { 
      text-shadow: 
        0 0 5px hsl(var(--neon-cyan)),
        0 0 10px hsl(var(--neon-cyan)),
        0 0 15px hsl(var(--neon-cyan)),
        0 0 20px hsl(var(--neon-cyan));
    }
    to { 
      text-shadow: 
        0 0 8px hsl(var(--neon-cyan)),
        0 0 16px hsl(var(--neon-cyan)),
        0 0 24px hsl(var(--neon-cyan)),
        0 0 32px hsl(var(--neon-cyan));
    }
  }

  .light .studycore-glow {
    animation: none;
    text-shadow: none;
  }

  /* Professional Components */
  .studycore-card {
    @apply bg-card border border-border rounded-xl shadow-lg backdrop-blur-sm transition-all duration-300;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.12);
  }

